1	import { useEffect, useState } from 'react';
2	import { supabase } from '../../lib/supabase';
3	import { WalletService } from '../../services/walletService';
4	import type { WalletTransaction, EscrowTransaction } from '../../services/walletService';
5	import { DollarSign, ArrowDownLeft, ArrowUpRight, History, Lock, Wallet, TrendingUp } from 'lucide-react';
6	import { useNavigate } from 'react-router-dom';
7	import DepositModal from '../../components/DepositModal';
8	
9	export default function CompanyWallet() {
10	    const navigate = useNavigate();
11	    const [loading, setLoading] = useState(true);
12	    const [balance, setBalance] = useState(0);
13	    const [transactions, setTransactions] = useState<WalletTransaction[]>([]);
14	    const [escrows, setEscrows] = useState<EscrowTransaction[]>([]);
15	    const [stats, setStats] = useState({ totalSpent: 0, inEscrow: 0 });
16	    const [isDepositModalOpen, setIsDepositModalOpen] = useState(false);
17	
18	    const fetchWalletData = async () => {
19	        const { data: { user } } = await supabase.auth.getUser();
20	        if (!user) return navigate('/login');
21	
22	        // 1. Get or create company wallet
23	        const wallet = await WalletService.getOrCreateWallet(user.id, 'company');
24	        if (wallet) {
25	            setBalance(wallet.balance);
26	        }
27	
28	        // 2. Fetch Transactions
29	        const txs = await WalletService.getTransactions(user.id);
30	        setTransactions(txs);
31	
32	        // 3. Fetch Escrows
33	        const companyEscrows = await WalletService.getCompanyEscrows(user.id);
34	        setEscrows(companyEscrows);
35	
36	        // 4. Calculate Stats
37	        const totalSpent = txs
38	            .filter(t => t.type === 'escrow_release' || (t.type === 'debit' && t.amount < 0))
39	            .reduce((acc, t) => acc + Math.abs(t.amount), 0);
40	
41	        const inEscrow = companyEscrows
42	            .filter(e => e.status === 'reserved')
43	            .reduce((acc, e) => acc + e.amount, 0);
44	
45	        setStats({ totalSpent, inEscrow });
46	
47	        setLoading(false);
48	    };
49	
50	    useEffect(() => {
51	        let isMounted = true;
52	        const init = async () => {
53	            await fetchWalletData(); // Load local data fast
54	
55	            // Background sync with Asaas silently
56	            const res = await WalletService.syncBalance();
57	            if (isMounted && res.success && res.hasUpdates) {
58	                await fetchWalletData(); // Refresh UI with new Asaas data if updates found
59	            }
60	        };
61	
62	        init();
63	        return () => { isMounted = false; };
64	    // eslint-disable-next-line react-hooks/exhaustive-deps -- init e fetchWalletData usam state setters estaveis, navigate estavel
65	    }, [navigate]);
66	
67	    const formatDate = (dateStr: string) => {
68	        return new Date(dateStr).toLocaleDateString('pt-BR', {
69	            day: '2-digit',
70	            month: 'short',
71	            year: 'numeric'
72	        });
73	    };
74	
75	    const getTransactionIcon = (type: string) => {
76	        switch (type) {
77	            case 'initial_balance': return <TrendingUp size={20} />;
78	            case 'escrow_reserve': return <Lock size={20} />;
79	            case 'escrow_release': return <ArrowUpRight size={20} />;
80	            case 'credit': return <ArrowDownLeft size={20} />;
81	            case 'platform_fee': return <DollarSign size={20} />;
82	            default: return <DollarSign size={20} />;
83	        }
84	    };
85	
86	    const getTransactionColor = (type: string, amount: number) => {
87	        if (type === 'platform_fee') {
88	            return 'text-orange-600 bg-orange-100';
89	        }
90	        if (type === 'initial_balance' || type === 'credit' || amount > 0) {
91	            return 'text-green-600 bg-green-100';
92	        }
93	        return 'text-red-600 bg-red-100';
94	    };
95	
96	    const getTransactionLabel = (t: WalletTransaction) => {
97	        if (t.type === 'credit') {
98	            return t.description || 'Deposito via PIX';
99	        }
100	        if (t.type === 'platform_fee') {
101	            return t.description || 'Taxa de servico';
102	        }
103	        return t.description || t.type;
104	    };
105	
106	    if (loading) return (
107	        <div className="flex flex-col gap-8 pb-12 max-w-4xl mx-auto animate-pulse">
108	            <div>
109	                <div className="h-10 bg-gray-200 rounded w-2/5 mb-2" />
110	                <div className="h-4 bg-gray-200 rounded w-1/2" />
111	            </div>
112	            <div className="h-36 bg-gray-200 rounded-2xl" />
113	            <div className="space-y-3">
114	                {[...Array(5)].map((_, i) => (
115	                    <div key={i} className="h-16 bg-gray-200 rounded-xl" />
116	                ))}
117	            </div>
118	        </div>
119	    );
120	
121	    return (
122	        <div className="flex flex-col gap-8 pb-12 font-sans text-accent max-w-4xl mx-auto">
123	
124	            <header>
125	                <h2 className="text-4xl font-black uppercase tracking-tighter mb-2">Carteira da Empresa</h2>
126	                <p className="text-gray-500">Gerencie seu saldo e pagamentos</p>
127	            </header>
128	
129	            {/* Main Balance Card */}
130	            <div className="bg-gradient-to-br from-blue-600 to-blue-800 text-white p-8 rounded-2xl border-2 border-black shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] relative overflow-hidden">
